alt:
def total_by_category(lines):
    totals = {}
    for line in lines:
        parts = line.split(",")
        if len(parts) != 2 or not parts[1].strip().lstrip("-").isdigit():
            continue
        totals[parts[0]] = totals.get(parts[0], 0) + int(parts[1])
    return totals
